Here is a complete web component implementation named `<x-details>`. It uses standard Web Component features (custom elements, shadow DOM, and slots).

### The Code

```html
<!-- x-details.js -->
<script type="module">
  class XDetails extends HTMLElement {
    constructor() {
      super();
      const root = this.attachShadow({ mode: 'open' });

      // Template
      const html = `
        <style>
          :host {
            --gap-size: 1rem;
            font-family: system-ui, sans-serif;
            --border-color: #ccc;
            --hover-bg: #f0f0f0;
          }

          .wrapper {
            display: flex;
            flex-direction: column;
            gap: var(--gap-size);
            width: 100%;
          }

          /* Header Section */
          .header-row {
            display: flex;
            align-items: center;
            width: 100%;
          }

          .toggle-btn {
            width: 40px;
            height: 40px;
            background: white;
            border: 2px solid var(--border-color);
            border-radius: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            margin-right: 15px;
            transition: all 0.2s ease;
            flex-shrink: 0;
          }

          .toggle-btn:hover {
            border-color: #666;
            background-color: var(--hover-bg);
          }

          .toggle-btn svg {
            width: 20px;
            height: 20px;
            fill: #333;
            transition: transform 0.2s;
          }

          .header-text {
            margin: 0;
            font-size: 1.25rem;
            font-weight: 600;
            border-bottom: 2px solid transparent;
            padding-bottom: 2px;
            color: inherit;
            min-height: 44px; /* Match header row height */
            display: block;
          }

          .header-text:hover {
            border-bottom-color: rgba(0,0,0,0.1);
          }

          /* Body Section */
          .body {
            display: flex;
            flex-direction: column;
            gap: var(--gap-size);
            opacity: 0;
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease-out, opacity 0.3s ease-out, visibility 0.3s;
            width: 100%;
          }

          .body.expanded {
            opacity: 1;
            max-height: 5000px; /* Arbitrary large number */
            visibility: visible;
            padding-left: 35px; /* Indent content under header */
          }

          .intro {
            font-size: 1rem;
            line-height: 1.5;
            padding: 0 10px;
          }

          .btn-action {
            align-self: flex-start;
            padding: 0.5rem 1rem;
            background-color: #4a90e2;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 0.9rem;
            display: none; /* Hidden by default */
          }

          .btn-action:hover {
            background-color: #357abd;
          }

          .btn-action.visible {
            display: inline-block;
          }

          /* Details Section */
          .details-content {
            padding-left: 35px; /* Align with body text */
            border-top: 1px solid #eee;
            padding-top: var(--gap-size);
            margin: var(--gap-size) 0 0 0;
            width: 100%;
          }

        </style>

        <div class="wrapper">
          <!-- The Clickable Header Area -->
          <div class="header-row">
            <button class="toggle-btn" aria-label="Toggle expansion">
              <svg viewBox="0 0 24 24"><path d="M12 7l-7.5 10.5L12 21l7.5-13.5L12 7z"/></svg>
            </button>
            <slot name="header" class="header-text"></slot>
          </div>

          <div class="body">
            <div class="intro">
              <slot name="intro"></slot>
            </div>

            <!-- Action Button -->
            <button id="expandBtn" class="btn-action">Expand More</button>
          </div>

          <div class="details-content">
            <slot name="details"></slot>
          </div>
        </div>
      `;
      root.innerHTML = html;
    }

    connectedCallback() {
      this.shadowRoot.querySelector('.body').addEventListener('transitionend', () => {
        // Optional: Clean up transitions after animation finishes
        this.shadowRoot.querySelector('.body').classList.remove('expanded');
        // If we needed to reset height manually, we'd do it here, 
        // but using opacity/max-height hides them nicely without manual cleanup for simple views.
      });

      const toggleBtn = this.shadowRoot.querySelector('.toggle-btn');
      const expandBtn = this.shadowRoot.getElementById('expandBtn');
      const body = this.shadowRoot.querySelector('.body');

      // Initialize state
      let isOpen = false;

      function toggle() {
        isOpen = !isOpen;
        body.classList.toggle('expanded', isOpen);
        updateButtonText(isOpen);
        updateIcon(isOpen);
        updateActionButtonVisibility(!isOpen); // Show button if NOT open
      }

      function updateButtonText(open) {
         const btnText = this.shadowRoot.querySelector('#expandBtn');
         btnText.textContent = open ? 'Collapse Less' : 'Expand More';
      }

      function updateIcon(open) {
         const svg = this.shadowRoot.querySelector('.toggle-btn svg');
         if (open) {
             // Down arrow
             svg.setAttribute('d', 'M0 0l24 24M0 24L24 0'); 
             svg.style.transform = 'rotate(180deg)'; // Rotate down visually
         } else {
             // Up arrow
             svg.setAttribute('d', 'M0 0l24 24M0 24L24 0'); 
             svg.style.transform = 'rotate(0deg)';
         }
      }

      function updateActionButtonVisibility(collapsed) {
          const btn = this.shadowRoot.getElementById('expandBtn');
          if (collapsed) btn.classList.add('visible');
          else btn.classList.remove('visible');
      }

      toggleBtn.addEventListener('click', toggle);
      expandBtn.addEventListener('click', toggle);
    }
  }

  customElements.define('x-details', XDetails);
</script>
```

### Usage Example

To use this component, add the script tag to your page first, then you can write your HTML exactly like you asked:

