<script type="module">
  // Import the logic defined above into a global scope (if running outside the module wrapper)
  window.xdetailsLogicScript = {}; 
  // For brevity, simply copy the file or ensure your server serves the js correctly.
  // Assuming this file is loaded directly via script src in production.
</script>

<x-details>
  <!-- Header is always visible on top -->
  <span slot="header">Configuration Settings</span>

  <!-- The "Intro" section is always shown below the header -->
