    Use the controls below to manage the device. This section remains visible even when the component is collapsed.
  </div>

  <!-- The main details content is hidden by default -->
  <div slot="details">
    <p><strong>Network:</strong> 192.168.1.45</p>
    <p><strong>Status:</strong> Online</p>
    <p><strong>Settings:</strong> High brightness</p>
  </div>
</x-details>

<div style="padding: 20px;">
  <!-- Simple button to test the internal "Expand More" feature -->
